B.amD=s(["300 ml de leche entera","1 pl\xe1tano","40 g de copos de avena","20 g de nueces o almendras"],t.s)
B.aqw=s(["Pela el pl\xe1tano y troc\xe9alo.","Echa todo en el vaso de la batidora.","Bate 1 minuto, hasta que no queden trozos.","T\xf3malo enseguida o ll\xe9valo en una botella cerrada (aguanta 1 d\xeda en la nevera)."],t.s)
B.b8h=new A.ab("batido","Batido energ\xe9tico",2,"1 raci\xf3n \xb7 ~570 kcal \xb7 20 g prote\xedna",B.amD,B.aqw,"Si por la ma\xf1ana no tienes hambre, empieza el d\xeda con el batido: se bebe mucho m\xe1s f\xe1cil que un plato.",570,20,B.a0,B.dh,!1)
B.arx=s(["2 rebanadas de pan","2 huevos","1 cucharadita de aceite de oliva","Sal","Opcional: jam\xf3n york o queso"],t.s)
B.aqy=s(["Tuesta el pan.","Bate los huevos con una pizca de sal.","Calienta una cucharadita de aceite en una sart\xe9n a fuego medio.","Echa los huevos y remueve sin parar con una esp\xe1tula 2-3 minutos, hasta que cuajen pero sigan jugosos.","Pon un chorrito de aceite en las tostadas y los huevos encima."],t.s)
B.b8a=new A.ab("tostadas-huevos","Tostadas con huevos revueltos",8,"1 raci\xf3n",B.arx,B.aqy,"Con prisa: bate los huevos en una taza y cali\xe9ntalos en el microondas en tandas de 30 segundos, removiendo entre medias. O usa 2 huevos cocidos el d\xeda de la compra.",370,20,B.cp,B.co,!1)
B.awg=s(["50 g de copos de avena","300 ml de leche entera","1 pl\xe1tano","20 g de nueces","1 cucharada de miel"],t.s)
B.aTg=s(["Pon la avena y la leche en un bol.","Calienta 2 minutos en el microondas (o en un cazo, removiendo).","A\xf1ade el pl\xe1tano en rodajas, las nueces troceadas y la miel."],t.s)
B.b7H=new A.ab("avena","Avena con leche, pl\xe1tano, nueces y miel",5,"1 raci\xf3n",B.awg,B.aTg,"Puedes dejarla preparada la noche antes en la nevera y tomarla fr\xeda.",670,21,B.cp,B.co,!1)
B.aM1=s(["40 g de copos de avena","2 huevos","1 pl\xe1tano maduro","Unas gotas de aceite","Miel para servir"],t.s)
B.axb=s(["Tritura la avena, los huevos y el pl\xe1tano hasta tener una masa espesa.",u.s,"Echa un cuchar\xf3n de masa por tortita.","Cuando salgan burbujas (1-2 minutos), dale la vuelta y deja 1 minuto m\xe1s.","S\xedrvelas con miel."],t.s)
B.b8K=new A.ab("tortitas-avena","Tortitas de avena",15,"1 raci\xf3n (4-5 tortitas)",B.aM1,B.axb,"Fuego bajo: si est\xe1 muy fuerte se queman por fuera y quedan crudas por dentro.",440,22,B.cp,B.co,!1)
B.alg=s(["90 g de macarrones","120 g de carne picada de ternera","100 g de tomate frito","1 cucharadita de aceite de oliva","Sal","Opcional: queso rallado"],t.s)
B.as7=s(["Hierve agua con sal y cuece los macarrones el tiempo que diga el paquete (10-12 minutos).","Mientras, dora la carne en una sart\xe9n con un chorrito de aceite y sal, deshaci\xe9ndola con la esp\xe1tula, 5-6 minutos.","A\xf1ade el tomate frito y deja 3 minutos a fuego bajo.",u.F],t.s)
B.b79=new A.ab("macarrones-carne","Macarrones con carne picada y tomate",20,"1 raci\xf3n",B.alg,B.as7,"Si un d\xeda te animas, ralla medio calabac\xedn dentro de la salsa: no se nota.",720,34,B.V,B.cL,!1)
B.awL=s(["170 g de pechuga de pollo","80 g de arroz","1 cucharadita de aceite de oliva","Sal","Ajo en polvo o piment\xf3n"],t.s)
B.aCo=s(["Cuece el arroz en agua con sal 15-18 minutos (o usa el arroz que dejaste cocido el d\xeda de la compra).","Filetea la pechuga fina y saz\xf3nala.","Calienta bien la plancha con unas gotas de aceite y haz el pollo 3-4 minutos por lado, hasta que no quede rosa por dentro.","S\xedrvelo con el arroz y un chorrito de aceite."],t.s)
B.b6Y=new A.ab("pollo-arroz","Pechuga de pollo a la plancha con arroz",20,"1 raci\xf3n",B.awL,B.aCo,"El arroz cocido aguanta 3-4 d\xedas en t\xe1per en la nevera.",510,45,B.V,B.dT,!1)
B.aq5=s(["1 kg de calabaza pelada","2 patatas","1 quesito por raci\xf3n (opcional)","Aceite de oliva","Sal"],t.s)
B.apj=s(["Pela la calabaza y las patatas y c\xf3rtalas en dados.","Ponlas en una olla, c\xfabrelas de agua y a\xf1ade sal y un chorrito de aceite.","Cuece 20-25 minutos, hasta que est\xe9n blandas.","Quita parte del agua y tritura con la batidora hasta que quede cremosa.","Al servir, a\xf1ade un quesito y remueve."],t.s)
B.b9g=new A.ab("crema-calabaza","Crema de calabaza",35,"4 raciones",B.aq5,B.apj,"Gu\xe1rdala en t\xe1pers de una raci\xf3n: 4 d\xedas en la nevera o 3 meses en el congelador. Sin tiempo, c\xf3mprala en brick.",170,5,B.V,B.eI,!1)
B.aF8=s(["3 calabacines","1 patata","2-3 quesitos","Aceite de oliva","Sal"],t.s)
B.akA=s(["Lava los calabacines (no hace falta pelarlos) y c\xf3rtalos en trozos. Pela y trocea la patata.","C\xfabrelos de agua en una olla con sal y un chorrito de aceite.","Cuece 15-20 minutos.","Quita parte del agua, a\xf1ade los quesitos y tritura hasta que quede fina."],t.s)
B.b7x=new A.ab("crema-calabacin","Crema de calabac\xedn",25,"3 raciones",B.aF8,B.akA,"Los quesitos le quitan el sabor a verdura y le dan cuerpo.",160,6,B.V,B.eI,!1)
B.akw=s(["80 g de arroz","150 g de pollo en dados","80 g de jud\xedas verdes congeladas","2 cucharadas de tomate frito","300 ml de agua o caldo","1 cucharadita de aceite, sal y piment\xf3n"],t.s)
B.ayW=s(["Dora el pollo en una cazuela con aceite y sal, 5 minutos.","A\xf1ade las jud\xedas y el tomate frito y rehoga 2 minutos.","Echa el arroz y una pizca de piment\xf3n y remueve 1 minuto.","A\xf1ade el agua caliente y cuece 15-18 minutos a fuego medio sin remover.","Deja reposar 5 minutos tapado."],t.s)
B.b81=new A.ab("arroz-pollo","Arroz con pollo y jud\xedas verdes",30,"1 raci\xf3n",B.akw,B.ayW,null,620,38,B.V,B.cL,!1)
B.auV=s(["1 lomo de salm\xf3n (descongelado la noche antes)","1 patata grande","1 cucharadita de aceite de oliva","Sal","Opcional: lim\xf3n"],t.s)
B.aLV=s(["Precalienta el horno a 200 \xb0C.","Lava la patata, c\xf3rtala en gajos, ponle aceite y sal y horn\xe9ala 25 minutos.","A\xf1ade el salm\xf3n a la bandeja con sal y aceite y hornea 12-15 minutos m\xe1s.","Est\xe1 hecho cuando se separa en l\xe1minas con el tenedor."],t.s)
B.b7d=new A.ab("salmon-patata","Salm\xf3n al horno con patata asada",40,"1 raci\xf3n",B.auV,B.aLV,"Para ir m\xe1s r\xe1pido: pincha la patata y dale 8 minutos de microondas antes de hornearla.",560,36,B.V,B.dT,!1)
B.aDE=s(["90 g de espaguetis","40 g de bacon","1 huevo + 1 yema","20 g de queso rallado","Pimienta","Sal"],t.s)
B.ax0=s(["Cuece la pasta en agua con sal.","Dora el bacon en taquitos en una sart\xe9n sin aceite, 4 minutos.","Bate el huevo, la yema y el queso con pimienta.","Escurre la pasta guardando medio vaso del agua de cocerla.","Fuera del fuego, mezcla la pasta con el bacon y a\xf1ade el huevo removiendo r\xe1pido, con un poco del agua, hasta que quede cremoso."],t.s)
B.b7U=new A.ab("carbonara","Espaguetis carbonara",15,"1 raci\xf3n",B.aDE,B.ax0,"Siempre fuera del fuego: si no, el huevo se cuaja y queda como un revuelto.",700,32,B.V,B.cL,!1)
B.atL=s(["3 huevos","1 patata grande",u._,"Sal"],t.s)
B.aw_=s(["Pela las patatas y c\xf3rtalas en l\xe1minas finas.","Fr\xedelas en una sart\xe9n con bastante aceite a fuego medio 15 minutos, hasta que est\xe9n tiernas.","Esc\xfarrelas y m\xe9zclalas con los huevos batidos y sal.","En una sart\xe9n peque\xf1a con 1 cucharada de aceite, echa la mezcla y cuaja 3-4 minutos.","Dale la vuelta con ayuda de un plato y deja 2 minutos m\xe1s."],t.s)
B.b7N=new A.ab("tortilla-patata","Tortilla de patata",30,"1 raci\xf3n grande",B.atL,B.aw_,"M\xe1s r\xe1pido y con menos aceite: haz las patatas 6-7 minutos en el microondas, tapadas, en vez de fre\xedrlas.",720,28,B.V,B.eI,!1)
B.amQ=s(["150 g de lomo de cerdo en filetes","100 ml de salsa de champi\xf1\xf3n de bote","1 patata grande","1 cucharadita de aceite de oliva","Sal"],t.s)
B.al3=s([u.hf,"Sazona los filetes y d\xf3ralos a fuego fuerte 2 minutos por lado.","Baja el fuego, a\xf1ade la salsa y deja 3-4 minutos.","S\xedrvelo con las patatas."],t.s)
B.b86=new A.ab("lomo-champinon","Lomo en salsa de champi\xf1\xf3n con patatas al horno",35,"1 raci\xf3n",B.amQ,B.al3,"Se puede hacer por lotes el jueves y guardar 3 d\xedas en la nevera.",610,37,B.V,B.dT,!1)
B.aBi=s(["180 g de merluza (descongelada la noche antes)","80 g de arroz","1 cucharadita de aceite de oliva","Sal","Ajo en polvo","Opcional: lim\xf3n"],t.s)
B.aGg=s(["Cuece el arroz o usa el que tengas cocido.","Seca bien la merluza con papel de cocina y saz\xf3nala.","Hazla en la plancha con aceite, primero por el lado de la piel 4 minutos y luego 2-3 minutos por el otro.","S\xedrvela con el arroz y un chorrito de aceite."],t.s)
B.b8O=new A.ab("merluza-arroz","Merluza a la plancha con arroz",20,"1 raci\xf3n",B.aBi,B.aGg,null,470,36,B.V,B.dT,!1)
B.asK=s(["90 g de pasta (h\xe9lices o macarrones)","2 latas de at\xfan","3 cucharadas de ma\xedz","8 aceitunas","\xbd pepino (opcional)","2 cucharaditas de aceite de oliva","Sal"],t.s)
B.aIW=s(["Cuece la pasta, esc\xfarrela y enfr\xedala con agua fr\xeda.","M\xe9zclala con el at\xfan escurrido, el ma\xedz, las aceitunas en rodajas y el pepino en dados.","Ali\xf1a con aceite y sal.","Gu\xe1rdala en un t\xe1per en la nevera."],t.s)
B.b8B=new A.ab("ensalada-pasta","Ensalada de pasta con at\xfan, ma\xedz y aceitunas",15,"1 t\xe1per",B.asK,B.aIW,"Aguanta 2 d\xedas en la nevera. Ideal para d\xedas de evento.",730,42,B.V,B.fi,!1)
B.axh=s(["3 huevos","Sal","1 cucharadita de aceite","Opcional: queso o jam\xf3n"],t.s)
B.auq=s(["Bate los huevos con sal.","Calienta el aceite en una sart\xe9n a fuego medio.","Echa los huevos y, cuando cuajen los bordes, dobla la tortilla por la mitad.","Deja 30 segundos m\xe1s y s\xedrvela."],t.s)
B.b7u=new A.ab("tortilla-francesa","Tortilla francesa",5,"1 raci\xf3n",B.axh,B.auq,null,300,23,B.V,B.eI,!1)
B.aHL=s(["1-2 hamburguesas de ternera","1 pan de hamburguesa o 2 rebanadas","1 loncha de queso","Tomate frito o tu salsa","1 patata mediana","1 cucharadita de aceite de oliva","Sal"],t.s)
B.aqT=s([u.hf,"Haz la hamburguesa en la plancha bien caliente, 3-4 minutos por lado.","Pon el queso encima el \xfaltimo minuto para que se funda.","Monta la hamburguesa en el pan con la salsa."],t.s)
B.b7F=new A.ab("hamburguesa","Hamburguesa casera con queso y patatas al horno",35,"1 raci\xf3n",B.aHL,B.aqT,null,750,37,B.V,B.dT,!1)
B.ald=s(["1-2 tortillas de wrap","120 g de pollo en tiras","1 loncha de queso","2 cucharadas de ma\xedz","\xbc de pepino en tiras","1 cucharadita de aceite, sal y piment\xf3n"],t.s)
B.aFU=s(["Saltea el pollo con aceite, sal y piment\xf3n 6-7 minutos.","Calienta la tortilla 20 segundos en una sart\xe9n.","Rell\xe9nala con el pollo, el queso, el ma\xedz y el pepino.","Enr\xf3llala doblando primero los extremos."],t.s)
B.b77=new A.ab("wrap-pollo","Wrap de pollo con queso, ma\xedz y pepino",15,"1 raci\xf3n",B.ald,B.aFU,"Envuelto en papel de aluminio sirve para llevar.",530,35,B.V,B.fi,!1)
B.aoN=s(["200 g de arroz","200 g de pollo troceado","100 g de lomo o costilla de cerdo","100 g de jud\xedas verdes","2 cucharadas de tomate frito","800 ml de agua o caldo","Aceite, sal, piment\xf3n","Colorante o azafr\xe1n"],t.s)
B.apR=s(["Dora la carne en la paellera con aceite y sal, 8 minutos.","A\xf1ade las jud\xedas y rehoga 3 minutos.","A\xf1ade el tomate y el piment\xf3n y remueve 1 minuto.","Echa el agua caliente y el colorante y deja que hierva.","Reparte el arroz: 10 minutos a fuego fuerte y 8 a fuego suave, sin remover.","Deja reposar 5 minutos tapada con un trapo."],t.s)
B.b9c=new A.ab("paella",u.gs,45,"2 raciones",B.aoN,B.apR,"La segunda raci\xf3n, a un t\xe1per para otro d\xeda o al congelador.",720,35,B.V,B.cL,!1)
B.aqf=s(["90 g de pasta","2 latas de at\xfan","100 g de tomate frito","Opcional: queso rallado"],t.s)
B.asi=s(["Cuece la pasta en agua con sal.","Calienta el tomate con el at\xfan escurrido 2 minutos.",u.F],t.s)
B.b7z=new A.ab("pasta-atun","Pasta con tomate y at\xfan",15,"1 raci\xf3n",B.aqf,B.asi,null,640,42,B.V,B.cL,!1)
B.aRb=s(["200 g de fideos de fideu\xe1 (del n.\xba 0 o del 1)","600 ml de fumet de pescado (de brick o casero)","200 g de gambas peladas","150 g de sepia o calamar en trozos","1 tomate maduro rallado","2 dientes de ajo picados","1 cucharadita de piment\xf3n dulce","Unas hebras de azafr\xe1n o colorante (opcional)","3 cucharadas de aceite de oliva","Sal","Alioli y lim\xf3n para servir"],t.s)
B.aS1=s(["Calienta el fumet en un cazo y d\xe9jalo a fuego m\xednimo. Tiene que estar muy caliente cuando lo eches.","En una paellera o sart\xe9n grande, calienta el aceite y dora la sepia 3-4 minutos. A\xf1ade las gambas, salt\xe9alas 1 minuto, s\xe1calas y res\xe9rvalas (la sepia se queda).","Echa el ajo y, antes de que se dore, el tomate rallado. Sofr\xede 5 minutos a fuego medio hasta que pierda el agua.","A\xf1ade los fideos y tu\xe9stalos 2-3 minutos removiendo, hasta que cojan color dorado.","Pon el piment\xf3n, remueve 10 segundos (sin que se queme) y echa 500 ml de fumet caliente con el azafr\xe1n. Prueba de sal.","Cocina a fuego medio-fuerte 8-10 minutos sin remover. Si se queda seco antes de tiempo, a\xf1ade un poco del fumet que sobra.","Cuando falten 2 minutos, reparte las gambas por encima.","Apaga y deja reposar 3 minutos tapada con un pa\xf1o. Si te gustan los fideos de punta, m\xe9tela 3-4 minutos al grill del horno.","Sirve con alioli y un chorro de lim\xf3n."],t.s)
B.b75=new A.ab("fideua","Fideu\xe1 de pescado y marisco",35,"2 raciones",B.aRb,B.aS1,"La proporci\xf3n es de 2,5 veces de fumet por el peso de fideos. Para ganar peso, acomp\xe1\xf1ala de pan y una cucharada de alioli (+100 kcal).",710,45,B.V,B.cL,!1)
B.atU=s(["250 g de lentejas pardinas","1 chorizo (unos 100 g) en rodajas","1 cebolla","1 zanahoria","1 pimiento verde","2 dientes de ajo","1 patata mediana","1 cucharadita de piment\xf3n dulce","1 hoja de laurel","2 cucharadas de aceite de oliva","Sal"],t.s)
B.aEF=s(["Lava las lentejas en un colador (las pardinas no necesitan remojo).","Pica la cebolla, el pimiento, el ajo y la zanahoria en trozos peque\xf1os.","En una olla con el aceite, sofr\xede las verduras 8 minutos a fuego medio.","A\xf1ade el chorizo y deja 2 minutos para que suelte su grasa.","Echa el piment\xf3n, remueve r\xe1pido y a\xf1ade las lentejas, el laurel y agua hasta cubrirlas dos dedos.","Cuando hierva, baja el fuego, a\xf1ade la patata en trozos (cascados, no cortados del todo) y cuece 30-35 minutos.","Prueba de sal al final y deja reposar 5 minutos."],t.s)
B.b7J=new A.ab("lentejas","Lentejas con chorizo y verduras",45,"3 raciones",B.atU,B.aEF,"Al d\xeda siguiente est\xe1n a\xfan mejor. Cong\xe9lalas en t\xe1pers de una raci\xf3n.",620,31,B.V,B.fh,!1)
B.aSh=s(["1 bote de garbanzos cocidos (400 g)","200 g de espinacas frescas o congeladas","2 huevos","2 dientes de ajo","1 rebanada de pan","1 cucharadita de comino (opcional)","1 cucharadita de piment\xf3n","3 cucharadas de aceite de oliva","Sal"],t.s)
B.aEw=s(["Cuece los huevos 10 minutos, enfr\xedalos y p\xe9lalos.","Lava los garbanzos del bote con agua y esc\xfarrelos.","En una sart\xe9n con el aceite, fr\xede los ajos laminados y la rebanada de pan hasta que est\xe9n dorados. S\xe1calos y m\xe1jalos con un tenedor.","En ese aceite, saltea las espinacas hasta que se reduzcan.","A\xf1ade los garbanzos, el majado, el comino, el piment\xf3n y un vaso peque\xf1o de agua. Cocina 5 minutos.","Sirve con los huevos en cuartos por encima."],t.s)
B.b7E=new A.ab("garbanzos-espinacas","Garbanzos con espinacas y huevo",20,"2 raciones",B.aSh,B.aEw,null,520,24,B.V,B.fh,!1)
B.ave=s(["350 g de pechuga o contramuslo de pollo","160 g de arroz (en crudo)","1 cebolla","1 lata de leche de coco (o 200 ml de nata para cocinar)","1 cucharada de curry en polvo","2 cucharadas de tomate frito","1 cucharada de aceite","Sal"],t.s)
B.awo=s(["Pon a cocer el arroz en agua con sal (15-18 minutos) y esc\xfarrelo.","Corta el pollo en dados y la cebolla en trozos peque\xf1os.","Dora el pollo en una sart\xe9n con el aceite, 5 minutos. S\xe1calo.","En la misma sart\xe9n pocha la cebolla 5 minutos, a\xf1ade el curry y remueve 30 segundos.","A\xf1ade la leche de coco y el tomate frito, vuelve a meter el pollo y cocina 8-10 minutos a fuego suave.","Sirve el pollo con su salsa sobre el arroz."],t.s)
B.b91=new A.ab("pollo-curry","Pollo al curry con arroz",30,"2 raciones",B.ave,B.awo,"Con leche de coco tiene m\xe1s calor\xedas que con nata ligera: perfecto para ganar peso.",930,51,B.V,B.dT,!1)
B.aQw=s(["500 g de carne picada (mixta o de ternera)","1 huevo","2 cucharadas de pan rallado","1 diente de ajo picado y perejil","Harina para rebozar","1 cebolla","400 g de tomate triturado","1 vaso peque\xf1o de caldo o agua","2 cucharadas de aceite de oliva (lo que absorben al fre\xedrlas)","Sal"],t.s)
